select id, no as number, status, uid as user_id, addr_id as address_book_id, ord_time as order_time, checkout_time, pay_method, pay_status, amount, remark, phone, address, user_name, consignee, cancel_reason, rejection_reason, cancel_time, estimated_delivery_time, delivery_status, delivery_time, pack_amount, tableware_number, tableware_status from ord
and no like concat('%',#{number},'%')
and phone like concat('%',#{phone},'%')
and uid = #{userId}
and status = #{status}
and ord_time >= #{beginTime}
and ord_time <= #{endTime}
order by ord_time desc

